   "acode": "function promiseAll(list) {\n  return new Promise((resolve, reject) => {\n    const results = [];\n    let done = 0;\n    if (list.length === 0) return resolve(results);\n    list.forEach((item, i) => {\n      Promise.resolve(item).then(value => {\n        results[i] = value;\n        if (++done === list.length) resolve(results);\n      }, reject);\n    });\n  });\n}"
